from datetime import datetime

now = datetime.now()
cur_year, cur_month = now.year, now.month
print('now', now, 'cur_year', cur_year, 'cur_month', cur_month)

# ensure we have token
print('has_amazon_token', 'amazon_token' in globals(), bool(globals().get('amazon_token')))

returns = []
i = 0
while True:
    page = apis.amazon.show_returns(access_token=amazon_token, page_index=i)
    # page is likely a list
    print('page', i, 'type', type(page), 'len', (len(page) if isinstance(page, list) else 'NA'))
    if not page:
        break
    returns.extend(page)
    i += 1
    if i > 50:
        break

print('total_returns', len(returns))

def parse_dt(s):
    if s is None:
        return None
    # handle possible trailing Z
    s2 = s.replace('Z','')
    try:
        return datetime.fromisoformat(s2)
    except Exception:
        # fallback
        for fmt in ['%Y-%m-%dT%H:%M:%S','%Y-%m-%d %H:%M:%S']:
            try:
                return datetime.strptime(s2, fmt)
            except Exception:
                pass
        return None

office_desk_returns = []
for r in returns:
    returned_at = parse_dt(r.get('returned_at'))
    name = (r.get('product_name') or '').lower()
    is_month = returned_at is not None and returned_at.year==cur_year and returned_at.month==cur_month
    # match 'office desk' semantics: must have 'desk' and 'office' somewhere in product_name
    is_office_desk = ('desk' in name) and ('office' in name)
    if is_month and is_office_desk:
        office_desk_returns.append({
            'return_id': r.get('return_id'),
            'order_id': r.get('order_id'),
            'product_name': r.get('product_name'),
            'returned_at': r.get('returned_at'),
            'initiated_at': r.get('initiated_at'),
            'quantity': r.get('quantity')
        })

print('office_desk_returns_count', len(office_desk_returns))
print('office_desk_returns', office_desk_returns[:20])
